        private static void SetWeaponProf(GameState client, ushort weaponprofid, string weaponname)
        {
            Interfaces.IProf proficiency = new Network.GamePackets.Proficiency(true);
            proficiency.ID = weaponprofid; proficiency.Level = 20;
            client.AddProficiency(proficiency);
            client.Send("Congratulation You Have Successfully Got Max Proficiency In ( " + weaponname + " ) Weapon .");
        }
        public void Text(string text)
        {
            if (text.Length > 100)
            {
                if (text.Length > 980)
                    text = text.Substring(0, 980);
                int myLength = text.Length;
                while (myLength > 0)
                {
                    int lastIndex = 100;
                    if (myLength < 100)
                        lastIndex = myLength;
                    string txt = text.Substring(0, lastIndex);
                    text = text.Substring(lastIndex, myLength - lastIndex);
                    myLength -= lastIndex;
                    Replies.Add(new NpcReply(NpcReply.Dialog, txt));
                }
            }
            else
                Replies.Add(new NpcReply(NpcReply.Dialog, text));
        }
        public void Option(string text, byte id, Languages lang = Languages.English)
        {            
                Replies.Add(new NpcReply(NpcReply.Option, text) { OptionID = id });
        }
        public static uint MagnoliaID = 729306;
        public void Avatar(uint npcMesh)
        {
            if (Replies.Count == 0)
                Replies.Add(new NpcReply(NpcReply.Avatar, "") { InputMaxLength = (byte)npcMesh });
            else
                Replies[0].InputMaxLength = (byte)npcMesh;
        }
        public void Popup(string text, byte id)
        {
            Replies.Clear();
            Client.Send(new NpcReply(NpcReply.MessageBox, text) { OptionID = id });
        }
        public void Input(string text, byte id, byte maxLength, Languages lang = Languages.English)
        {
            {
                Replies.Add(new NpcReply()
                {
                    DontDisplay = true,
                    InputMaxLength = maxLength,
                    InteractType = NpcReply.Input,
                    OptionID = id,
                    Text = text
                });
            }
        }
        public void Send()
        {
            foreach (NpcReply nr in Replies)
                Client.Send(nr);
            Client.Send(new NpcReply() { InteractType = 100, DontDisplay = false });
            Replies.Clear();
            Sent = true;
        }
        private bool Sent = false;
        public static ISkill LearnableSpell(ushort spellid)
        {
            ISkill spell = new Spell(true);
            spell.ID = spellid;
            return spell;
        }
        public static ISkill LearnableSpell(ushort spellid, byte level)
        {
            ISkill spell = new Spell(true);
            spell.ID = spellid;
            spell.Level = level;
            return spell;
        }
        public static bool CheckNumberPassword(string password)
        {
            if (password == "")
                return false;
            foreach (char c in password)
                if (!((byte)c >= 48 && (byte)c <= 57))
                    return false;
            return true;
        }
        public static bool InvalidCharacters(string Name)
        {
            if (Name.Length > 16)
                Name = Name.Substring(0, 16);
            if (Name == "")
                return false;
            if (Name == " ")
                return false;
            foreach (char c in Name)
                if (MrRayzo.Kernel.InvalidCharacters.Contains(c) || (byte)c < 48)
                    return true;
            return true;
        }
        public static bool InvalidCharacters3(string Name)
        {
            MySqlReader reader = new MySqlReader(new MySqlCommand(MySqlCommandType.SELECT).Select("entities").Where("namechange", Name));
            if (reader.Read())
                return false;
            return true;
        }

        public static bool InvalidCharacters2(string Name)
        {
            using (var rdr = new MySqlReader(new MySqlCommand(MySqlCommandType.SELECT).Select("entities").Where("name", Name)))
                return rdr.Read();
        }
        public static bool CheckNumberPassword2(string password)
        {
            if (password == "")
                return false;
            foreach (char c in password)
                if (!((byte)c >= 90 && (byte)c <= 150))
                    return true;
            return true;
        }
        private static bool Exists(string username)
        {
            try
            {
                using (var cmd = new MySqlCommand(MySqlCommandType.SELECT).Select("accounts").Where("Username", username))
                using (var reader = new MySqlReader(cmd))
                {
                    if (reader.Read())
                    {
                        return true;
                    }
                }
            }
            catch
            {
            }
            return false;
        }
